<?php use app\services\{Ui,Workflow};use yii\helpers\Html;$request=Yii::$app->request; ?>
<section class="card" id="application-status-report"><div class="card-heading"><div><h2><?= $personal?'Mening arizalarim va ularning holati':'Arizalar va ularning holati' ?></h2><p class="muted">Jami <?= (int)$activityTotal ?> ta ariza. Dastlabki ball reytingga qo‘shilmaydi; faqat yakuniy tasdiqlangan ball hisoblanadi.</p></div></div>
<?php if(!$activityRows): ?><?= Ui::empty('Tanlangan davr va filtrlar bo‘yicha arizalar yo‘q.') ?><?php else: ?><div class="table-wrap"><table><thead><tr><th>Ariza / faoliyat</th><?php if(!$personal): ?><th>Xodim</th><?php endif ?><th>Davr / sana</th><th>Holat / joriy bosqich</th><th class="number">Dastlabki ball</th><th class="number">Tasdiqlangan ball</th><th></th></tr></thead><tbody>
<?php foreach($activityRows as $application):$steps=json_decode($application['route_snapshot']??'[]',true);$current=$steps[(int)$application['step']]['name']??'Tekshiruv kutilmoqda';$stage=match($application['status']){'draft'=>'Tekshiruvga yuborilmagan','returned'=>'Xodim to‘ldirishi kutilmoqda','rejected'=>'Rad etilgan','approved'=>'Barcha bosqichlar yakunlangan',default=>$current}; ?>
<tr><td><b>#<?= (int)$application['id'] ?> · <?= Ui::h($application['title']) ?></b><small><?= Ui::h($application['indicator']) ?></small></td><?php if(!$personal): ?><td><?= Ui::h($application['employee']) ?></td><?php endif ?><td><?= Ui::h($application['period']) ?><small><?= Ui::h($application['activity_date']) ?></small></td><td><?= Ui::status($application['status']) ?><span class="report-application-stage"><?= Ui::h($stage) ?></span></td><td class="number"><?= in_array($application['status'],['submitted','review'],true)?Ui::money($application['score_cents']):'—' ?></td><td class="number score"><?= $application['status']==='approved'?Ui::money($application['score_cents']):'—' ?></td><td><?= Html::a('Ko‘rish →',['kpi/view','id'=>$application['id']],['class'=>'text-link']) ?></td></tr>
<?php endforeach ?></tbody></table></div><div class="pagination no-print"><?php if($activityPage>1)echo Html::a('← Oldingi',array_merge(['kpi/reports'],$request->get(),['activity_page'=>$activityPage-1]),['class'=>'button secondary']); ?><span><?= $activityPage ?> / <?= max(1,(int)ceil($activityTotal/25)) ?></span><?php if($activityPage*25<$activityTotal)echo Html::a('Keyingi →',array_merge(['kpi/reports'],$request->get(),['activity_page'=>$activityPage+1]),['class'=>'button secondary']); ?></div><?php endif ?></section>
